def getFileContents(vault_repo_id, path, ref=None, refresh_cache=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0147000" if __import__("os").path.isdir("./environment_mix/0147000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_bool(x, default=False):
        if x is None:
            return default
        if isinstance(x, bool):
            return x
        return None

    def _validate_str(name, v, min_len=1, max_len=None):
        if not isinstance(v, str):
            return f"{name} must be a string"
        if len(v) < min_len:
            return f"{name} must be at least {min_len} characters"
        if max_len is not None and len(v) > max_len:
            return f"{name} must be at most {max_len} characters"
        return None

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_call(api_key_id, endpoint, status, latency_ms, workspace_id=None, vault_repo_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "obgh_req_" + hashlib.sha256((str(time.time_ns()) + endpoint + str(api_key_id)).encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "vault_repo_id": vault_repo_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    # Basic validation
    e = _validate_str("vault_repo_id", vault_repo_id, 1, 200)
    if e:
        return _err("VALIDATION_ERROR", e)
    e = _validate_str("path", path, 1, 2000)
    if e:
        return _err("VALIDATION_ERROR", e)
    if ref is not None:
        e = _validate_str("ref", ref, 1, 255)
        if e:
            return _err("VALIDATION_ERROR", e)
    refresh_cache_b = _parse_bool(refresh_cache, default=False)
    if refresh_cache_b is None:
        return _err("VALIDATION_ERROR", "refresh_cache must be a boolean")

    # Authenticate: find any active api key that can access this vault repo and workspace (ambient auth)
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    vault_repos = _load("vault_repos.json")
    vault_files = _load("vault_files.json")

    vr = next((r for r in vault_repos if isinstance(r, dict) and r.get("id") == vault_repo_id), None)
    if vr is None:
        # Log attempt with unknown key
        return _err("NOT_FOUND", "vault_repo_id not found")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == vr.get("workspace_id")), None)
    if ws is None:
        return _err("NOT_FOUND", "workspace for vault_repo_id not found")

    # Workspace access rules
    if ws.get("status") == "deleted":
        return _err("UNAUTHORIZED", "Workspace is deleted")
    if ws.get("status") == "suspended":
        return _err("UNAUTHORIZED", "Workspace is suspended")

    usable_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("workspace_id") != ws.get("id"):
            continue
        if k.get("status") != "active":
            continue
        # prerequisite: must have a positive rate limit
        rlm = k.get("rate_limit_per_minute")
        if not isinstance(rlm, int) or rlm < 1:
            continue
        usable_key = k
        break

    if usable_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this workspace")

    # Enforce per-key rate limit using request_logs if present; otherwise allow
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != usable_key.get("id"):
                continue
            ts = _parse_iso(r.get("created_at"))
            if ts is None:
                continue
            # Normalize to naive UTC for comparison
            ts_naive = ts.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            if ts_naive >= window_start:
                cnt += 1
        if cnt >= int(usable_key.get("rate_limit_per_minute")):
            _log_call(usable_key.get("id"), "getFileContents", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    # Determine branch/ref
    branch = ref if ref is not None else vr.get("default_branch")
    if not isinstance(branch, str) or not branch:
        _log_call(usable_key.get("id"), "getFileContents", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unable to resolve branch/ref")

    # Find cached record
    rec = None
    for f in vault_files:
        if not isinstance(f, dict):
            continue
        if f.get("vault_repo_id") == vault_repo_id and f.get("branch") == branch and f.get("path") == path:
            rec = f
            break

    # Optional refresh: offline implementation cannot fetch from GitHub; simulate refresh only by touching indexed_at when record exists and repo active.
    # If record missing and refresh_cache requested, we cannot fabricate: return NOT_FOUND.
    if refresh_cache_b:
        if vr.get("status") != "active":
            # can't refresh when repo not active; proceed with cache as-is
            pass
        else:
            if rec is None:
                _log_call(usable_key.get("id"), "getFileContents", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "NOT_FOUND")
                return _err("NOT_FOUND", "File not found in cache and refresh is unavailable offline")
            # enforce cache constraints already in schema; if present, ensure consistency
            # Touch indexed_at/updated_at
            now = _now()
            rec["indexed_at"] = now
            rec["updated_at"] = now
            # Persist mutation
            _save("vault_files.json", vault_files)

    if rec is None or rec.get("deleted") is True:
        _log_call(usable_key.get("id"), "getFileContents", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "NOT_FOUND")
        return _err("NOT_FOUND", "File not found")

    # Update key last_used_at
    usable_key["last_used_at"] = _now()
    usable_key["updated_at"] = _now()
    _save("api_keys.json", api_keys)

    latency = (time.time() - t0) * 1000
    _log_call(usable_key.get("id"), "getFileContents", "ok", latency, ws.get("id"), vault_repo_id)

    return {
        "file": rec,
        "vault_repo": {
            "id": vr.get("id"),
            "github_owner": vr.get("github_owner"),
            "github_repo": vr.get("github_repo"),
            "default_branch": vr.get("default_branch"),
            "status": vr.get("status"),
        },
        "ref": branch,
    }

def searchFiles(vault_repo_id, query, branch=None, path_prefix=None, extensions=None, include_deleted=None, sort=None, order=None, limit=None, cursor=None, refresh_cache=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0147000" if __import__("os").path.isdir("./environment_mix/0147000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _parse_bool(x, default=False):
        if x is None:
            return default
        if isinstance(x, bool):
            return x
        return None

    def _validate_str(name, v, min_len=1, max_len=None):
        if not isinstance(v, str):
            return f"{name} must be a string"
        if len(v) < min_len:
            return f"{name} must be at least {min_len} characters"
        if max_len is not None and len(v) > max_len:
            return f"{name} must be at most {max_len} characters"
        return None

    def _log_call(api_key_id, endpoint, status, latency_ms, workspace_id=None, vault_repo_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "obgh_req_" + hashlib.sha256((str(time.time_ns()) + endpoint + str(api_key_id)).encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "vault_repo_id": vault_repo_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _encode_cursor(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    t0 = time.time()

    e = _validate_str("vault_repo_id", vault_repo_id, 1, 200)
    if e:
        return _err("VALIDATION_ERROR", e)
    e = _validate_str("query", query, 1, 2000)
    if e:
        return _err("VALIDATION_ERROR", e)

    if branch is not None:
        e = _validate_str("branch", branch, 1, 255)
        if e:
            return _err("VALIDATION_ERROR", e)
    if path_prefix is not None:
        e = _validate_str("path_prefix", path_prefix, 1, 2000)
        if e:
            return _err("VALIDATION_ERROR", e)

    if extensions is not None:
        if not isinstance(extensions, list) or any(not isinstance(x, str) or not x for x in extensions):
            return _err("VALIDATION_ERROR", "extensions must be an array of non-empty strings")
        extensions_norm = [x.lower().lstrip(".") for x in extensions]
    else:
        extensions_norm = None

    include_deleted_b = _parse_bool(include_deleted, default=False)
    if include_deleted_b is None:
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean")

    refresh_cache_b = _parse_bool(refresh_cache, default=False)
    if refresh_cache_b is None:
        return _err("VALIDATION_ERROR", "refresh_cache must be a boolean")

    sort = sort or "updated_at"
    order = order or "desc"
    if sort not in ("path", "name", "updated_at", "size_bytes"):
        return _err("VALIDATION_ERROR", "Unsupported sort")
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Unsupported order")

    if limit is None:
        limit_n = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        limit_n = limit

    # Resolve vault + workspace + authenticate (ambient)
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    vault_repos = _load("vault_repos.json")
    vault_files = _load("vault_files.json")

    vr = next((r for r in vault_repos if isinstance(r, dict) and r.get("id") == vault_repo_id), None)
    if vr is None:
        return _err("NOT_FOUND", "vault_repo_id not found")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == vr.get("workspace_id")), None)
    if ws is None:
        return _err("NOT_FOUND", "workspace for vault_repo_id not found")

    if ws.get("status") == "deleted":
        return _err("UNAUTHORIZED", "Workspace is deleted")
    if ws.get("status") == "suspended":
        return _err("UNAUTHORIZED", "Workspace is suspended")

    usable_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("workspace_id") != ws.get("id"):
            continue
        if k.get("status") != "active":
            continue
        rlm = k.get("rate_limit_per_minute")
        if not isinstance(rlm, int) or rlm < 1:
            continue
        usable_key = k
        break
    if usable_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this workspace")

    # Rate limit
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != usable_key.get("id"):
                continue
            ts = _parse_iso(r.get("created_at"))
            if ts is None:
                continue
            ts_naive = ts.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            if ts_naive >= window_start:
                cnt += 1
        if cnt >= int(usable_key.get("rate_limit_per_minute")):
            _log_call(usable_key.get("id"), "searchFiles", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    br = branch if branch is not None else vr.get("default_branch")
    if not isinstance(br, str) or not br:
        _log_call(usable_key.get("id"), "searchFiles", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unable to resolve branch")

    # Refresh cache: offline no-op (do not fabricate)
    # Deterministic and observable behaviour: only touch vault_repo.updated_at if active and refresh requested.
    if refresh_cache_b and vr.get("status") == "active":
        vr["updated_at"] = _now()
        _save("vault_repos.json", vault_repos)

    # Cursor decode
    start = 0
    cur_obj = None
    if cursor is not None:
        cur_obj = _decode_cursor(cursor)
        if cur_obj is None or cur_obj.get("v") != 1 or cur_obj.get("vault_repo_id") != vault_repo_id:
            _log_call(usable_key.get("id"), "searchFiles", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed cursor")
        if cur_obj.get("branch") != br or cur_obj.get("sort") != sort or cur_obj.get("order") != order:
            _log_call(usable_key.get("id"), "searchFiles", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cursor does not match request parameters")
        start = int(cur_obj.get("start", 0))

    # Query parsing: basic "filename/path/content" contains tokens; qualifiers: path:, ext:
    q = query.strip()
    tokens = [t for t in q.split() if t]
    text_terms = []
    q_path_prefix = None
    q_exts = []
    for t in tokens:
        if t.startswith("path:") and len(t) > 5:
            q_path_prefix = t[5:]
        elif t.startswith("ext:") and len(t) > 4:
            q_exts.append(t[4:].lower().lstrip("."))
        else:
            text_terms.append(t.lower())

    eff_path_prefix = path_prefix if path_prefix is not None else q_path_prefix
    eff_exts = set(extensions_norm) if extensions_norm is not None else (set(q_exts) if q_exts else None)

    def _matches_text(rec):
        if not text_terms:
            return True
        hay = " ".join([
            (rec.get("name") or ""),
            (rec.get("path") or ""),
            (rec.get("content_text") or ""),
        ]).lower()
        return all(term in hay for term in text_terms)

    # Filter records
    rows = []
    for r in vault_files:
        if not isinstance(r, dict):
            continue
        if r.get("vault_repo_id") != vault_repo_id:
            continue
        if r.get("branch") != br:
            continue
        if not include_deleted_b and r.get("deleted") is True:
            continue
        if eff_path_prefix is not None:
            p = r.get("path")
            if not isinstance(p, str) or not p.startswith(eff_path_prefix):
                continue
        if eff_exts is not None:
            ext = r.get("extension")
            if not isinstance(ext, str) or ext.lower() not in eff_exts:
                continue
        # Content search must only scan content_text; we comply by using content_text only (not content_base64)
        if not _matches_text(r):
            continue
        rows.append(r)

    total = len(rows)

    # Sort
    def _key(r):
        if sort == "path":
            return (r.get("path") or "")
        if sort == "name":
            return (r.get("name") or "")
        if sort == "size_bytes":
            v = r.get("size_bytes")
            return (-1 if v is None else int(v))
        # updated_at
        return (r.get("updated_at") or "")

    reverse = (order == "desc")
    rows.sort(key=_key, reverse=reverse)

    page = rows[start:start + limit_n]
    next_cursor = None
    has_more = start + limit_n < total
    if has_more:
        next_cursor = _encode_cursor({
            "v": 1,
            "vault_repo_id": vault_repo_id,
            "branch": br,
            "sort": sort,
            "order": order,
            "start": start + limit_n,
        })

    # Update key usage + log
    usable_key["last_used_at"] = _now()
    usable_key["updated_at"] = _now()
    _save("api_keys.json", api_keys)

    latency = (time.time() - t0) * 1000
    _log_call(usable_key.get("id"), "searchFiles", "ok", latency, ws.get("id"), vault_repo_id)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit_n,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "branch": br,
            "sort": sort,
            "order": order,
        },
    }

def searchIssues(vault_repo_id, query, type=None, state=None, labels=None, author_login=None, sort=None, order=None, limit=None, cursor=None, refresh_cache=None, **_extra):
