        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    t0 = time.time()

    e = _validate_str("vault_repo_id", vault_repo_id, 1, 200)
    if e:
        return _err("VALIDATION_ERROR", e)
    e = _validate_str("query", query, 1, 4000)
    if e:
        return _err("VALIDATION_ERROR", e)

    type = type or "any"
    if type not in ("issue", "discussion", "any"):
        return _err("VALIDATION_ERROR", "Invalid type")
    state = state or "any"
    if state not in ("open", "closed", "merged", "answered", "unknown", "any"):
        return _err("VALIDATION_ERROR", "Invalid state")

    if labels is not None:
        if not isinstance(labels, list) or any(not isinstance(x, str) or not x for x in labels):
            return _err("VALIDATION_ERROR", "labels must be an array of non-empty strings")
        labels_norm = [x.strip() for x in labels if x.strip()]
    else:
        labels_norm = []

    if author_login is not None:
        e = _validate_str("author_login", author_login, 1, 200)
        if e:
            return _err("VALIDATION_ERROR", e)

    sort = sort or "updated_at"
