    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Unsupported order")

    if limit is None:
        limit_n = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        limit_n = limit

    refresh_cache_b = _parse_bool(refresh_cache, default=False)
    if refresh_cache_b is None:
        return _err("VALIDATION_ERROR", "refresh_cache must be a boolean")

    # Resolve + authenticate
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    vault_repos = _load("vault_repos.json")
    activity = _load("repo_activity.json")

    vr = next((r for r in vault_repos if isinstance(r, dict) and r.get("id") == vault_repo_id), None)
    if vr is None:
        return _err("NOT_FOUND", "vault_repo_id not found")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == vr.get("workspace_id")), None)
    if ws is None:
        return _err("NOT_FOUND", "workspace for vault_repo_id not found")

    if ws.get("status") == "deleted":
        return _err("UNAUTHORIZED", "Workspace is deleted")
    if ws.get("status") == "suspended":
        return _err("UNAUTHORIZED", "Workspace is suspended")

    usable_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("workspace_id") != ws.get("id"):
            continue
        if k.get("status") != "active":
            continue
        rlm = k.get("rate_limit_per_minute")
        if not isinstance(rlm, int) or rlm < 1:
            continue
        usable_key = k
        break
    if usable_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this workspace")

    # Rate limit
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != usable_key.get("id"):
                continue
            ts = _parse_iso(r.get("created_at"))
            if ts is None:
                continue
            ts_naive = ts.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            if ts_naive >= window_start:
                cnt += 1
        if cnt >= int(usable_key.get("rate_limit_per_minute")):
            _log_call(usable_key.get("id"), "searchIssues", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    # Refresh cache offline no-op; touch vault_repo.updated_at if active
    if refresh_cache_b and vr.get("status") == "active":
        vr["updated_at"] = _now()
        _save("vault_repos.json", vault_repos)

    # Cursor
    start = 0
    if cursor is not None:
        cur_obj = _decode_cursor(cursor)
        if cur_obj is None or cur_obj.get("v") != 1 or cur_obj.get("vault_repo_id") != vault_repo_id:
            _log_call(usable_key.get("id"), "searchIssues", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed cursor")
        if cur_obj.get("type") != type or cur_obj.get("state") != state or cur_obj.get("sort") != sort or cur_obj.get("order") != order:
            _log_call(usable_key.get("id"), "searchIssues", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cursor does not match request parameters")
        start = int(cur_obj.get("start", 0))

    # Parse qualifiers from query: is:issue, is:discussion, author:, label:, state:
    q = query.strip()
    tokens = [t for t in q.split() if t]
    q_type = None
    q_author = None
    q_state = None
    q_labels = []
    text_terms = []
    for t in tokens:
        tl = t.lower()
        if tl == "is:issue":
            q_type = "issue"
        elif tl == "is:discussion":
            q_type = "discussion"
        elif tl.startswith("author:") and len(t) > 7:
            q_author = t[7:]
        elif tl.startswith("state:") and len(t) > 6:
            q_state = tl[6:]
        elif tl.startswith("label:") and len(t) > 6:
            q_labels.append(t[6:])
        else:
            text_terms.append(t.lower())

    eff_type = type if type != "any" else (q_type or "any")
    eff_state = state if state != "any" else (q_state or "any")
    eff_author = author_login if author_login is not None else q_author
    eff_labels = labels_norm[:] if labels_norm else []
    if q_labels:
        eff_labels.extend([x for x in q_labels if isinstance(x, str) and x])

    def _matches_text(r):
        if not text_terms:
            return True
        hay = " ".join([
            (r.get("title") or ""),
            (r.get("body_text") or ""),
            (r.get("author_login") or ""),
        ]).lower()
        return all(term in hay for term in text_terms)

    want_types = {"issue", "discussion"} if eff_type == "any" else {eff_type}

    rows = []
    for r in activity:
        if not isinstance(r, dict):
            continue
        if r.get("vault_repo_id") != vault_repo_id:
            continue
        if r.get("activity_type") not in ("issue", "discussion"):
            continue
        if r.get("status") == "deleted":
            continue
        if r.get("activity_type") not in want_types:
            continue
        if eff_state != "any":
            if (r.get("state") or "unknown") != eff_state:
                continue
        if eff_author is not None:
            if (r.get("author_login") or "") != eff_author:
                continue
        if eff_labels:
            row_labels = r.get("labels")
            if not isinstance(row_labels, list):
                row_labels = []
            row_label_set = set([x for x in row_labels if isinstance(x, str)])
            if any(lbl not in row_label_set for lbl in eff_labels):
                continue
        if not _matches_text(r):
            continue
        rows.append(r)

    total = len(rows)

    def _key(r):
        if sort == "github_number":
            v = r.get("github_number")
            return (0 if v is None else int(v))
        if sort == "committed_at":
            return (r.get("committed_at") or "")
        if sort == "created_at":
            return (r.get("created_at") or "")
        return (r.get("updated_at") or "")

    rows.sort(key=_key, reverse=(order == "desc"))
    page = rows[start:start + limit_n]
    has_more = start + limit_n < total
    next_cursor = None
    if has_more:
        next_cursor = _encode_cursor({
            "v": 1,
            "vault_repo_id": vault_repo_id,
            "type": type,
            "state": state,
            "sort": sort,
            "order": order,
            "start": start + limit_n,
        })

    usable_key["last_used_at"] = _now()
    usable_key["updated_at"] = _now()
    _save("api_keys.json", api_keys)

    latency = (time.time() - t0) * 1000
    _log_call(usable_key.get("id"), "searchIssues", "ok", latency, ws.get("id"), vault_repo_id)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit_n,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
            "type": type,
            "state": state,
        },
    }

def getCommitHistory(vault_repo_id, path=None, ref=None, since=None, until=None, author_login=None, include_patches=None, sort=None, order=None, limit=None, cursor=None, refresh_cache=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0147000" if __import__("os").path.isdir("./environment_mix/0147000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_dt(s, name):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{name} must be an ISO 8601 string")
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            else:
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{name} must be a valid ISO 8601 date-time")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _parse_bool(x, default=False):
        if x is None:
            return default
        if isinstance(x, bool):
            return x
        return None

    def _validate_str(name, v, min_len=1, max_len=None):
        if v is None:
            return None
        if not isinstance(v, str):
            return f"{name} must be a string"
        if len(v) < min_len:
            return f"{name} must be at least {min_len} characters"
        if max_len is not None and len(v) > max_len:
            return f"{name} must be at most {max_len} characters"
        return None

    def _log_call(api_key_id, endpoint, status, latency_ms, workspace_id=None, vault_repo_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "obgh_req_" + hashlib.sha256((str(time.time_ns()) + endpoint + str(api_key_id)).encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "vault_repo_id": vault_repo_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _encode_cursor(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    t0 = time.time()

    e = _validate_str("vault_repo_id", vault_repo_id, 1, 200)
    if e:
        return _err("VALIDATION_ERROR", e)
    e = _validate_str("path", path, 1, 2000)
    if e:
        return _err("VALIDATION_ERROR", e)
    e = _validate_str("ref", ref, 1, 255)
    if e:
        return _err("VALIDATION_ERROR", e)
    e = _validate_str("author_login", author_login, 1, 200)
    if e:
        return _err("VALIDATION_ERROR", e)

    since_dt, err = _parse_iso_dt(since, "since")
    if err:
        return err
    until_dt, err = _parse_iso_dt(until, "until")
    if err:
        return err
    if since_dt and until_dt and since_dt > until_dt:
        return _err("VALIDATION_ERROR", "since must be <= until")

    include_patches_b = _parse_bool(include_patches, default=False)
    if include_patches_b is None:
        return _err("VALIDATION_ERROR", "include_patches must be a boolean")

    refresh_cache_b = _parse_bool(refresh_cache, default=False)
    if refresh_cache_b is None:
        return _err("VALIDATION_ERROR", "refresh_cache must be a boolean")

    sort = sort or "committed_at"
    order = order or "desc"
    if sort != "committed_at":
        return _err("VALIDATION_ERROR", "Unsupported sort")
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Unsupported order")

    if limit is None:
        limit_n = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        limit_n = limit

    # Resolve + authenticate
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    vault_repos = _load("vault_repos.json")
    activity = _load("repo_activity.json")

    vr = next((r for r in vault_repos if isinstance(r, dict) and r.get("id") == vault_repo_id), None)
    if vr is None:
        return _err("NOT_FOUND", "vault_repo_id not found")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == vr.get("workspace_id")), None)
    if ws is None:
        return _err("NOT_FOUND", "workspace for vault_repo_id not found")

    if ws.get("status") == "deleted":
        return _err("UNAUTHORIZED", "Workspace is deleted")
    if ws.get("status") == "suspended":
        return _err("UNAUTHORIZED", "Workspace is suspended")

    usable_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("workspace_id") != ws.get("id"):
            continue
        if k.get("status") != "active":
            continue
        rlm = k.get("rate_limit_per_minute")
        if not isinstance(rlm, int) or rlm < 1:
            continue
        usable_key = k
        break
    if usable_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this workspace")

    # Rate limit
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != usable_key.get("id"):
                continue
            ts = _parse_iso(r.get("created_at"))
            if ts is None:
                continue
            ts_naive = ts.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            if ts_naive >= window_start:
                cnt += 1
        if cnt >= int(usable_key.get("rate_limit_per_minute")):
            _log_call(usable_key.get("id"), "getCommitHistory", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    # Resolve branch/ref (accepted but not used for filtering cached commits)
    _resolved_ref = ref if ref is not None else vr.get("default_branch")

    # Refresh cache offline no-op; touch vault_repo.updated_at if active
    if refresh_cache_b and vr.get("status") == "active":
        vr["updated_at"] = _now()
        _save("vault_repos.json", vault_repos)

    # Cursor
    start = 0
    if cursor is not None:
        cur_obj = _decode_cursor(cursor)
        if cur_obj is None or cur_obj.get("v") != 1 or cur_obj.get("vault_repo_id") != vault_repo_id:
            _log_call(usable_key.get("id"), "getCommitHistory", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed cursor")
        # Must match key request params
        if cur_obj.get("order") != order or cur_obj.get("path") != (path or None) or cur_obj.get("author_login") != (author_login or None):
            _log_call(usable_key.get("id"), "getCommitHistory", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cursor does not match request parameters")
        if cur_obj.get("since") != (since or None) or cur_obj.get("until") != (until or None):
            _log_call(usable_key.get("id"), "getCommitHistory", "error", (time.time() - t0) * 1000, ws.get("id"), vault_repo_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cursor does not match request parameters")
        start = int(cur_obj.get("start", 0))

    # Business rule: Sync integrity if last_sync_at not null, sha must exist among commits for this vault
    if vr.get("last_sync_at") is not None:
        need_sha = vr.get("last_sync_commit_sha")
        if isinstance(need_sha, str) and need_sha:
            exists = False
            for r in activity:
                if isinstance(r, dict) and r.get("vault_repo_id") == vault_repo_id and r.get("activity_type") == "commit" and r.get("sha") == need_sha and r.get("status") != "deleted":
                    exists = True
                    break
            if not exists:
                # Do not hard-fail the endpoint; but reflect as cache error on vault_repo for observability.
                vr["status"] = "error" if vr.get("status") in ("active", "syncing") else vr.get("status")
                vr["last_error"] = "Sync integrity error: last_sync_commit_sha missing from commit cache"
                vr["updated_at"] = _now()
                _save("vault_repos.json", vault_repos)

    # Filter commits
    rows = []
    for r in activity:
        if not isinstance(r, dict):
            continue
        if r.get("vault_repo_id") != vault_repo_id:
            continue
        if r.get("activity_type") != "commit":
            continue
        if r.get("status") == "deleted":
            continue
        # Required by schema: commit must have sha and committed_at; skip malformed
        if not r.get("sha") or not r.get("committed_at"):
            continue
        if author_login is not None and (r.get("author_login") or "") != author_login:
            continue
        ca = _parse_iso(r.get("committed_at"))
        if ca is None:
            continue
        ca_utc = ca.astimezone(datetime.timezone.utc)
        if since_dt and ca_utc <= since_dt:
            continue
        if until_dt and ca_utc > until_dt:
            continue
        # Path filter: only possible if patches are stored and contain that path; otherwise cannot infer.
        if path is not None:
            patches = r.get("patches")
            if not isinstance(patches, dict) or path not in patches:
                continue
        rows.append(r)

    rows.sort(key=lambda r: r.get("committed_at") or "", reverse=(order == "desc"))
    total = len(rows)
    page = rows[start:start + limit_n]

    # If include_patches is false, strip patches from returned objects (do not mutate stored cache)
    out = []
    for r in page:
        if include_patches_b:
            out.append(r)
        else:
            rr = dict(r)
            rr["patches"] = None
            out.append(rr)

    has_more = start + limit_n < total
    next_cursor = None
    if has_more:
        next_cursor = _encode_cursor({
            "v": 1,
            "vault_repo_id": vault_repo_id,
            "order": order,
            "start": start + limit_n,
            "path": path or None,
            "author_login": author_login or None,
            "since": since or None,
            "until": until or None,
        })

    usable_key["last_used_at"] = _now()
    usable_key["updated_at"] = _now()
    _save("api_keys.json", api_keys)

    latency = (time.time() - t0) * 1000
    _log_call(usable_key.get("id"), "getCommitHistory", "ok", latency, ws.get("id"), vault_repo_id)

    return {
        "data": out,
        "meta": {
            "total": total,
            "limit": limit_n,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "ref": _resolved_ref,
            "sort": "committed_at",
            "order": order,
            "include_patches": include_patches_b,
        },
    }

def getAuthContext(api_key=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0147000" if __import__("os").path.isdir("./environment_mix/0147000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(endpoint, api_key_id, workspace_id, http_status, error_code=None):
        logs = _load("request_logs.json")
        logs = _ensure_list(logs)
        logs.append({
            "id": "obgh_req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": http_status,
            "error_code": error_code,
            "latency_ms": int((time.time() - start) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _choose_key_for_request(api_key_param):
        keys = _ensure_list(_load("api_keys.json"))
        workspaces = _ensure_list(_load("workspaces.json"))

        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}

        # Candidate selection: if param is provided, accept id OR key_prefix OR workspace_id (common caller mistake)
        candidates = []
        if api_key_param is not None:
            if not isinstance(api_key_param, str):
                return None, _err("VALIDATION_ERROR", "api_key must be a string")
            val = api_key_param.strip()
            if not val:
                return None, _err("VALIDATION_ERROR", "api_key must be a non-empty string when provided")
            for k in keys:
                if not isinstance(k, dict):
                    continue
                if k.get("id") == val or k.get("key_prefix") == val or k.get("workspace_id") == val:
                    candidates.append(k)
        else:
            # Ambient auth: find any key that can serve (active key + workspace not deleted)
            for k in keys:
                if not isinstance(k, dict):
                    continue
                if k.get("status") != "active":
                    continue
                ws = ws_by_id.get(k.get("workspace_id"))
                if not isinstance(ws, dict):
                    continue
                if ws.get("status") == "deleted":
                    continue
                candidates.append(k)

        # Must authenticate via an active api_keys record
        candidates = [k for k in candidates if isinstance(k, dict) and k.get("status") == "active"]

        # Workspace must exist and not be deleted; suspended rejected by default policy
        valid = []
        for k in candidates:
            ws = ws_by_id.get(k.get("workspace_id"))
            if not isinstance(ws, dict):
                continue
            if ws.get("status") == "deleted":
                continue
            if ws.get("status") == "suspended":
                continue
            valid.append((k, ws))

        if not valid:
            return None, None

        # Deterministic selection: earliest created_at then id
        def _sort_key(pair):
            k, _ws = pair
            return (_parse_dt(k.get("created_at")) or datetime.datetime.min, k.get("id") or "")
        valid.sort(key=_sort_key)
        return valid[0], None  # (key, ws) packed in tuple

    chosen, err = _choose_key_for_request(api_key)
    if err is not None:
        _log("getAuthContext", None, None, 400, err["error"]["code"])
        return err

    if chosen is None:
        # no valid key/workspace combination found
        _log("getAuthContext", None, None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing, invalid, or revoked API key (or workspace not accessible)")

    api_key_row, ws_row = chosen

    # Rate limiting: per key per minute using request_logs
    rate_limit = api_key_row.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int) or not (1 <= rate_limit <= 6000):
        # If datastore is inconsistent, fall back to a safe default rather than breaking auth.
        rate_limit = 60

    logs = _ensure_list(_load("request_logs.json"))
    window_start = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_row.get("id"):
            continue
        t = _parse_dt(r.get("created_at"))
        if t is None:
            continue
        if t >= window_start:
            recent += 1

    if recent >= rate_limit:
        _log("getAuthContext", api_key_row.get("id"), ws_row.get("id"), 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate_limit, window_seconds=60, used=recent)

    # Update last_used_at (mutation with effect)
    keys = _ensure_list(_load("api_keys.json"))
    updated = False
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            updated = True
            api_key_row = k
            break
    if updated:
        _save("api_keys.json", keys)

    # Call log must be written for every call
    _log("getAuthContext", api_key_row.get("id"), ws_row.get("id"), 200, None)

    return {
        "api_key": {
            "id": api_key_row.get("id"),
            "workspace_id": api_key_row.get("workspace_id"),
            "name": api_key_row.get("name"),
            "key_prefix": api_key_row.get("key_prefix"),
            "status": api_key_row.get("status"),
            "rate_limit_per_minute": api_key_row.get("rate_limit_per_minute"),
            "last_used_at": api_key_row.get("last_used_at"),
            "created_at": api_key_row.get("created_at"),
            "updated_at": api_key_row.get("updated_at"),
        },
        "workspace": {
            "id": ws_row.get("id"),
            "name": ws_row.get("name"),
            "status": ws_row.get("status"),
            "plan": ws_row.get("plan"),
            "created_at": ws_row.get("created_at"),
            "updated_at": ws_row.get("updated_at"),
        },
        "policy": {
            "allow_suspended_reads": False,
            "allow_suspended_writes": False
        },
        "rate_limit": {
            "limit_per_minute": rate_limit,
            "used_in_current_window": recent,
            "remaining_in_current_window": max(0, rate_limit - recent),
            "window_seconds": 60
        }
    }

def listVaultRepos(workspace_id=None, status=None, visibility=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0147000" if __import__("os").path.isdir("./environment_mix/0147000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, api_key_id, workspace_id_resolved, status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "obgh_req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id_resolved,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - start) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if workspace_id is not None and not isinstance(workspace_id, str):
        _log("listVaultRepos", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must be a string")
    if status is not None:
        if not isinstance(status, str):
            _log("listVaultRepos", None, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "syncing", "error", "disabled", "any"):
            _log("listVaultRepos", None, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status filter")
    if visibility is not None:
        if not isinstance(visibility, str):
            _log("listVaultRepos", None, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "visibility must be a string")
        if visibility not in ("public", "private", "internal", "any"):
            _log("listVaultRepos", None, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid visibility filter")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("listVaultRepos", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 100:
        _log("listVaultRepos", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        _log("listVaultRepos", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Ambient auth: find an active key with accessible workspace; prefer requested workspace if provided.
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    active_keys.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))

    resolved_key = None
    resolved_ws = None

    def _ws_accessible(ws):
        if not ws or not isinstance(ws, dict):
            return False
        if ws.get("status") == "deleted":
            return False
        if ws.get("status") == "suspended":
            return False
        return True

    if workspace_id:
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not _ws_accessible(ws):
            _log("listVaultRepos", None, workspace_id, 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Workspace is not accessible")
        for k in active_keys:
            if k.get("workspace_id") == workspace_id:
                resolved_key = k
                resolved_ws = ws
                break
        if not resolved_key:
            _log("listVaultRepos", None, workspace_id, 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No active API key for the requested workspace")
    else:
        for k in active_keys:
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
            if _ws_accessible(ws):
                resolved_key = k
                resolved_ws = ws
                break
        if not resolved_key:
            _log("listVaultRepos", None, None, 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Missing, invalid, or revoked API key")

    # Rate limit check
    rate = resolved_key.get("rate_limit_per_minute")
    if not isinstance(rate, int):
        rate = 60
    rate = max(1, min(6000, rate))

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    used = sum(
        1 for r in logs
        if isinstance(r, dict) and r.get("api_key_id") == resolved_key.get("id") and (r.get("created_at") or "") >= window_start
    )
    if used >= rate:
        _log("listVaultRepos", resolved_key.get("id"), resolved_ws.get("id"), 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rate, used_in_last_minute=used)

    # Update last_used_at
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == resolved_key.get("id"):
            api_keys[i] = {**k, "last_used_at": now, "updated_at": now}
            _save("api_keys.json", api_keys)
            break

    # Cursor decode: base64("offset:<int>")
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                _log("listVaultRepos", resolved_key.get("id"), resolved_ws.get("id"), 400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("listVaultRepos", resolved_key.get("id"), resolved_ws.get("id"), 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    vault_repos = _load("vault_repos.json")
    if not isinstance(vault_repos, list):
        vault_repos = []

    rows = [r for r in vault_repos if isinstance(r, dict) and r.get("workspace_id") == resolved_ws.get("id")]

    if status and status != "any":
        rows = [r for r in rows if r.get("status") == status]
    if visibility and visibility != "any":
        # Stored enum includes "unknown"; tool wants internal; treat internal as private for cached value
        if visibility == "internal":
            rows = [r for r in rows if r.get("visibility") in ("private", "unknown")]
        else:
            rows = [r for r in rows if r.get("visibility") == visibility]

    # Deterministic ordering
    rows.sort(key=lambda r: ((r.get("github_owner") or "").lower(), (r.get("github_repo") or "").lower(), r.get("id") or ""))

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    _log("listVaultRepos", resolved_key.get("id"), resolved_ws.get("id"), 200, None)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

