        if not isinstance(default_branch, str) or not (1 <= len(default_branch) <= 255):
            _log("createVaultRepo", None, workspace_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "default_branch must be a string length 1..255")
