            _log("createVaultRepo", None, workspace_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "visibility must be one of public, private, internal")
    else:
        # Stored enum doesn't have internal; map internal/private both to "private" for cache.
        visibility = "unknown"
    stored_visibility = "private" if visibility == "internal" else visibility

    if not isinstance(auth_type, str) or auth_type not in ("github_pat", "github_app", "oauth_token"):
        _log("createVaultRepo", None, workspace_id, 400, "VALIDATION_ERROR")
