    resolved_key = None
    resolved_ws = None

    if workspace_id:
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not _ws_accessible(ws):
            _log("createVaultRepo", None, workspace_id, 401, "UNAUTHORIZED")
