        for k in active_keys:
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
            if _ws_accessible(ws):
                resolved_key = k
                resolved_ws = ws
                break
        if not resolved_key:
            _log("createVaultRepo", None, None, 401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Missing, invalid, or revoked API key")

    # Rate limit check
    rate = resolved_key.get("rate_limit_per_minute")
    if not isinstance(rate, int):
        rate = 60
    rate = max(1, min(6000, rate))

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    used = sum(
        1 for r in logs
        if isinstance(r, dict) and r.get("api_key_id") == resolved_key.get("id") and (r.get("created_at") or "") >= window_start
    )
    if used >= rate:
        _log("createVaultRepo", resolved_key.get("id"), resolved_ws.get("id"), 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rate, used_in_last_minute=used)

