    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == resolved_key.get("id"):
            api_keys[i] = {**k, "last_used_at": now, "updated_at": now}
            _save("api_keys.json", api_keys)
            break

    vault_repos = _load("vault_repos.json")
    if not isinstance(vault_repos, list):
        vault_repos = []

    # Uniqueness: unique(workspace_id, github_owner, github_repo)
    for r in vault_repos:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") == resolved_ws.get("id") and (r.get("github_owner") or "").lower() == github_owner.lower() and (r.get("github_repo") or "").lower() == github_repo.lower():
            _log("createVaultRepo", resolved_key.get("id"), resolved_ws.get("id"), 409, "CONFLICT")
            return _err("CONFLICT", "A vault repo for this owner/repo already exists in the workspace")

    # Map auth_type to stored enum: github_app, pat, none
    stored_auth_type = {"github_app": "github_app", "github_pat": "pat", "oauth_token": "pat"}.get(auth_type)
    if stored_auth_type is None:
        _log("createVaultRepo", resolved_key.get("id"), resolved_ws.get("id"), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid auth_type")

