    # Instead: enforce deterministic ordering anyway; set_as_default is acknowledged via no-op metadata change.
    if set_as_default:
        # Touch workspace updated_at to reflect configuration change (best-effort within given schema)
        for i, w in enumerate(workspaces):
            if isinstance(w, dict) and w.get("id") == resolved_ws.get("id"):
                workspaces[i] = {**w, "updated_at": now}
                _save("workspaces.json", workspaces)
                break

    _log("createVaultRepo", resolved_key.get("id"), resolved_ws.get("id"), 201, None)
    return {"data": new_row}

def updateVaultRepo(vault_repo_id, default_branch=None, auth_type=None, auth_ref=None, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0147000" if __import__("os").path.isdir("./environment_mix/0147000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _as_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _save_rows(filename, rows):
        existing = _load(filename)
        if isinstance(existing, dict) and "rows" in existing and isinstance(existing["rows"], list):
            existing["rows"] = rows
            _save(filename, existing)
        else:
            _save(filename, rows)

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- request logging + rate limit (best-effort; must not break tool) ----
    def _log(endpoint, api_key_id, workspace_id, http_status, error_code=None):
        logs_raw = _load("request_logs.json")
        logs = _as_rows(logs_raw)
        logs.append(
            {
                "id": "obgh_req_" + uuid.uuid4().hex[:24],
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": http_status,
                "error_code": error_code,
                "latency_ms": int((time.time() - start) * 1000),
                "created_at": now,
            }
        )
        _save_rows("request_logs.json", logs)

    def _rate_limited(api_key_row):
        limit = api_key_row.get("rate_limit_per_minute")
        if not isinstance(limit, int) or limit < 1:
            return False, None

        logs_raw = _load("request_logs.json")
        logs = _as_rows(logs_raw)

        window_start = now_dt - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                s = ts[:-1] if ts.endswith("Z") else ts
                dt = datetime.datetime.fromisoformat(s)
            except Exception:
                continue
            if dt >= window_start:
                count += 1

        if count >= limit:
            retry_after = 60
            return True, retry_after
        return False, None

    # ---- input validation (types/enums/ranges) ----
    endpoint = "updateVaultRepo"
    if not isinstance(vault_repo_id, str) or not vault_repo_id:
        # Can't authenticate to log; still attempt ambient auth for logging
        vault_repo_id = vault_repo_id  # keep
        # fallthrough to ambient auth selection; will error as validation below after auth
        return _err("VALIDATION_ERROR", "vault_repo_id must be a non-empty string")

    if default_branch is not None:
        if not isinstance(default_branch, str) or not (1 <= len(default_branch) <= 255):
            return _err(
                "VALIDATION_ERROR",
                "default_branch must be a string with length between 1 and 255",
                field="default_branch",
            )

    if auth_type is not None:
        if not isinstance(auth_type, str):
            return _err("VALIDATION_ERROR", "auth_type must be a string", field="auth_type")
        if auth_type not in ("github_pat", "github_app", "oauth_token"):
            return _err(
                "VALIDATION_ERROR",
                "auth_type must be one of: github_pat, github_app, oauth_token",
                field="auth_type",
                allowed=["github_pat", "github_app", "oauth_token"],
            )

    if auth_ref is not None and not isinstance(auth_ref, str):
        return _err("VALIDATION_ERROR", "auth_ref must be a string", field="auth_ref")

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string", field="status")
        if status not in ("active", "disabled"):
            return _err(
                "VALIDATION_ERROR",
                "status must be one of: active, disabled",
                field="status",
                allowed=["active", "disabled"],
            )

    # ---- ambient authentication resolution: must find an ACTIVE api key AND an accessible workspace ----
    api_keys = _as_rows(_load("api_keys.json"))
    workspaces = _as_rows(_load("workspaces.json"))
    vault_repos = _as_rows(_load("vault_repos.json"))

    # locate the vault repo first (exists irrespective of auth)
    vlt = None
    for r in vault_repos:
        if isinstance(r, dict) and r.get("id") == vault_repo_id:
            vlt = r
            break
    if not vlt:
        # still log a request if possible by selecting any active key; otherwise just return
        key_for_log = None
        ws_for_log = None
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                key_for_log = k
                ws_for_log = k.get("workspace_id")
                break
        if key_for_log:
            limited, ra = _rate_limited(key_for_log)
            if limited:
                _log(endpoint, key_for_log.get("id"), ws_for_log, 429, "RATE_LIMIT")
                return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=ra)
            _log(endpoint, key_for_log.get("id"), ws_for_log, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "vault_repo_id not found", vault_repo_id=vault_repo_id)

    ws_id = vlt.get("workspace_id")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == ws_id:
            ws = w
            break
    if not ws:
        # broken FK in datastore; treat as NOT_FOUND for access scope
        key_for_log = None
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                key_for_log = k
                break
        if key_for_log:
            limited, ra = _rate_limited(key_for_log)
            if limited:
                _log(endpoint, key_for_log.get("id"), ws_id, 429, "RATE_LIMIT")
                return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=ra)
            _log(endpoint, key_for_log.get("id"), ws_id, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "workspace not found for vault repo", workspace_id=ws_id, vault_repo_id=vault_repo_id)

    # workspace access policy
    if ws.get("status") == "deleted":
        # find any active key for this workspace to log; if none, try any active key; else unauthorized
        candidate_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("workspace_id") == ws_id]
        key = candidate_keys[0] if candidate_keys else None
        if not key:
            any_active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
            key = any_active[0] if any_active else None
        if key:
            limited, ra = _rate_limited(key)
            if limited:
                _log(endpoint, key.get("id"), ws_id, 429, "RATE_LIMIT")
                return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=ra)
            _log(endpoint, key.get("id"), ws_id, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is deleted and cannot be accessed", workspace_id=ws_id)

    # suspended: default reject (no explicit enable flag exists in schema)
    if ws.get("status") == "suspended":
        # same key resolution as above
        candidate_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("workspace_id") == ws_id]
        key = candidate_keys[0] if candidate_keys else None
        if not key:
            any_active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
            key = any_active[0] if any_active else None
        if key:
            limited, ra = _rate_limited(key)
            if limited:
                _log(endpoint, key.get("id"), ws_id, 429, "RATE_LIMIT")
                return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=ra)
            _log(endpoint, key.get("id"), ws_id, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is suspended; reads may be disallowed by policy", workspace_id=ws_id)

    # must authenticate via an active api_key for this workspace
    active_keys_for_ws = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("workspace_id") == ws_id]
    if not active_keys_for_ws:
        any_active = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
        key_for_log = any_active[0] if any_active else None
        if key_for_log:
            limited, ra = _rate_limited(key_for_log)
            if limited:
                _log(endpoint, key_for_log.get("id"), ws_id, 429, "RATE_LIMIT")
                return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=ra)
            _log(endpoint, key_for_log.get("id"), ws_id, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this workspace", workspace_id=ws_id)

    api_key = active_keys_for_ws[0]

    limited, ra = _rate_limited(api_key)
    if limited:
        _log(endpoint, api_key.get("id"), ws_id, 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=ra)

    # ---- apply updates with business rules ----
    # Note: server schema uses auth_type enum ['github_app','pat','none']; tool accepts ['github_pat','github_app','oauth_token'].
    # Map tool values to stored enum.
    mapped_auth_type = None
    if auth_type is not None:
        if auth_type == "github_app":
            mapped_auth_type = "github_app"
        elif auth_type in ("github_pat", "oauth_token"):
            mapped_auth_type = "pat"
        else:
            # shouldn't happen due to validation, but be safe
            _log(endpoint, api_key.get("id"), ws_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid auth_type", field="auth_type")

    # status transition only between active <-> disabled (other states server-managed)
    if status is not None:
        current = vlt.get("status")
        if current not in ("active", "disabled", "syncing", "error"):
            _log(endpoint, api_key.get("id"), ws_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Vault repo status is invalid in store", current_status=current)
        if status not in ("active", "disabled"):
            _log(endpoint, api_key.get("id"), ws_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be active or disabled", field="status")
        if current != status:
            allowed = {
                "active": {"syncing", "disabled", "error"},
                "syncing": {"active", "error", "disabled"},
                "error": {"syncing", "disabled"},
                "disabled": {"active"},
            }
            if status not in allowed.get(current, set()):
                _log(endpoint, api_key.get("id"), ws_id, 409, "INVALID_TRANSITION")
                return _err(
                    "INVALID_TRANSITION",
                    "Illegal status transition for vault repo",
                    vault_repo_id=vault_repo_id,
                    from_status=current,
                    to_status=status,
                    allowed_to=sorted(list(allowed.get(current, set()))),
                )

    # uniqueness constraint: unique(workspace_id, github_owner, github_repo) unaffected here (no update fields), so no check needed.

    changed = False
    if default_branch is not None and default_branch != vlt.get("default_branch"):
        vlt["default_branch"] = default_branch
        changed = True

    if mapped_auth_type is not None and mapped_auth_type != vlt.get("auth_type"):
        vlt["auth_type"] = mapped_auth_type
        changed = True

    if auth_ref is not None and auth_ref != vlt.get("auth_ref"):
        vlt["auth_ref"] = auth_ref
        changed = True

    if status is not None and status != vlt.get("status"):
        vlt["status"] = status
        changed = True

    if not changed:
        # idempotent success; still update api key last_used_at + log
        api_key["last_used_at"] = now
        api_key["updated_at"] = now
        _save_rows("api_keys.json", api_keys)
        _log(endpoint, api_key.get("id"), ws_id, 200, None)
        return {"vault_repo": vlt}

    # Sync integrity rule is about last_sync_commit_sha only when last_sync_at not null.
    # This endpoint does NOT modify last_sync_at/last_sync_commit_sha, so it must not newly fail the request.
    # However, to preserve integrity on existing store, we can only enforce if this update changes those fields (it doesn't).
    # Therefore no conflict here.

    vlt["updated_at"] = now

    # persist vault_repos
    for i, r in enumerate(vault_repos):
        if isinstance(r, dict) and r.get("id") == vault_repo_id:
            vault_repos[i] = vlt
            break
    _save_rows("vault_repos.json", vault_repos)

    # update api key usage
    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    _save_rows("api_keys.json", api_keys)

    _log(endpoint, api_key.get("id"), ws_id, 200, None)
    return {"vault_repo": vlt}

def syncVaultRepo(vault_repo_id, mode=None, ref=None, include=None, since=None, force=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0147000" if __import__("os").path.isdir("./environment_mix/0147000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- request log / quota helpers (best-effort; must not raise) ---
    def _log(status, api_key_id=None, workspace_id=None, vault_repo_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "obgh_req_" + uuid.uuid4().hex[:24],
                "endpoint": "syncVaultRepo",
                "timestamp": now,
                "status": status,
                "latency_ms": int((time.time() - _t0) * 1000),
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "vault_repo_id": vault_repo_id,
                "error_code": error_code
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # --- authenticate (ambient): must find an active api key that can serve this request ---
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    vault_repos = _load("vault_repos.json")
    vault_files = _load("vault_files.json")
    repo_activity = _load("repo_activity.json")

    # Validate inputs
    if not isinstance(vault_repo_id, str) or not vault_repo_id:
        _log("error", error_code="VALIDATION_ERROR", vault_repo_id=vault_repo_id)
        return _err("VALIDATION_ERROR", "vault_repo_id must be a non-empty string.")
    if mode is not None and mode not in ("full", "incremental"):
        _log("error", error_code="VALIDATION_ERROR", vault_repo_id=vault_repo_id)
        return _err("VALIDATION_ERROR", "mode must be one of: full, incremental.")
    if ref is not None and (not isinstance(ref, str) or not ref.strip()):
        _log("error", error_code="VALIDATION_ERROR", vault_repo_id=vault_repo_id)
        return _err("VALIDATION_ERROR", "ref must be a non-empty string when provided.")
    if include is not None:
        if not isinstance(include, list) or any((not isinstance(x, str)) for x in include):
            _log("error", error_code="VALIDATION_ERROR", vault_repo_id=vault_repo_id)
            return _err("VALIDATION_ERROR", "include must be an array of strings.")
        allowed_inc = {"files", "commits", "issues_discussions"}
        if any(x not in allowed_inc for x in include):
            _log("error", error_code="VALIDATION_ERROR", vault_repo_id=vault_repo_id)
            return _err("VALIDATION_ERROR", "include items must be one of: files, commits, issues_discussions.")
    if since is not None:
        if not isinstance(since, str) or not since:
            _log("error", error_code="VALIDATION_ERROR", vault_repo_id=vault_repo_id)
            return _err("VALIDATION_ERROR", "since must be an ISO-8601 timestamp string.")
        # parse ISO-8601 (accept trailing Z)
        try:
            _s = since
            if _s.endswith("Z"):
                _s = _s[:-1] + "+00:00"
            datetime.datetime.fromisoformat(_s)
        except Exception:
            _log("error", error_code="VALIDATION_ERROR", vault_repo_id=vault_repo_id)
            return _err("VALIDATION_ERROR", "since must be a valid ISO-8601 timestamp.")
    if force is not None and not isinstance(force, bool):
        _log("error", error_code="VALIDATION_ERROR", vault_repo_id=vault_repo_id)
        return _err("VALIDATION_ERROR", "force must be a boolean when provided.")

    # Locate vault repo
    vr = next((r for r in vault_repos if isinstance(r, dict) and r.get("id") == vault_repo_id), None)
    if not vr:
        _log("error", error_code="NOT_FOUND", vault_repo_id=vault_repo_id)
        return _err("NOT_FOUND", "Vault repo not found.")

    ws_id = vr.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
    if not ws:
        _log("error", error_code="UNAUTHORIZED", vault_repo_id=vault_repo_id)
        return _err("UNAUTHORIZED", "Workspace not accessible.")

    # Workspace accessibility rules
    if ws.get("status") == "deleted":
        _log("error", error_code="UNAUTHORIZED", workspace_id=ws_id, vault_repo_id=vault_repo_id)
        return _err("UNAUTHORIZED", "Workspace is deleted.")
    if ws.get("status") == "suspended":
        _log("error", error_code="UNAUTHORIZED", workspace_id=ws_id, vault_repo_id=vault_repo_id)
        return _err("UNAUTHORIZED", "Workspace is suspended.")

    # Find an active API key for this workspace (ambient auth)
    # Also enforce per-key rate limit using request_logs if available.
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"]
    if not active_keys:
        _log("error", error_code="UNAUTHORIZED", workspace_id=ws_id, vault_repo_id=vault_repo_id)
        return _err("UNAUTHORIZED", "No active API key available for this workspace.")

    # Determine candidate key that is not rate-limited
    def _within_last_minute(ts_iso, now_dt):
        try:
            s = ts_iso
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return (now_dt - dt.astimezone(datetime.timezone.utc)).total_seconds() < 60
        except Exception:
            return False

    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    chosen_key = None
    for k in sorted(active_keys, key=lambda x: (str(x.get("id") or ""), str(x.get("created_at") or ""))):
        rl = k.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1:
            continue
        recent = 0
        kid = k.get("id")
        for rec in logs:
            if isinstance(rec, dict) and rec.get("api_key_id") == kid and isinstance(rec.get("timestamp"), str):
                if _within_last_minute(rec["timestamp"], now_dt):
                    recent += 1
        if recent < rl:
            chosen_key = k
            break

    if not chosen_key:
        _log("error", error_code="RATE_LIMIT", workspace_id=ws_id, vault_repo_id=vault_repo_id)
        return _err("RATE_LIMIT", "Rate limit exceeded for available API keys.")

    api_key_id = chosen_key.get("id")

    # Vault status gating rules
    vstatus = vr.get("status")
    if vstatus == "disabled":
        _log("error", api_key_id=api_key_id, workspace_id=ws_id, vault_repo_id=vault_repo_id, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Vault repo is disabled; syncing is not allowed.")
    if vstatus == "syncing":
        _log("error", api_key_id=api_key_id, workspace_id=ws_id, vault_repo_id=vault_repo_id, error_code="CONFLICT")
        return _err("CONFLICT", "A sync is already in progress for this vault repo.")
    if vstatus == "error" and not force:
        _log("error", api_key_id=api_key_id, workspace_id=ws_id, vault_repo_id=vault_repo_id, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Vault repo is in error; set force=true to attempt a sync.")

    # Defaults
    if include is None:
        include = ["files", "commits", "issues_discussions"]
    if mode is None:
        mode = "incremental"
    if ref is None:
        ref = vr.get("default_branch")

    if not isinstance(ref, str) or not ref:
        _log("error", api_key_id=api_key_id, workspace_id=ws_id, vault_repo_id=vault_repo_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "ref/default_branch is missing; cannot determine what to sync.")

    # Mark vault as syncing (persist)
    # enforce lifecycle transitions
    allowed_trans = {
        "active": {"syncing", "disabled", "error"},
        "syncing": {"active", "error", "disabled"},
        "error": {"syncing", "disabled"},
        "disabled": {"active"},
    }
    if vstatus not in allowed_trans or "syncing" not in allowed_trans.get(vstatus, set()):
        _log("error", api_key_id=api_key_id, workspace_id=ws_id, vault_repo_id=vault_repo_id, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot transition vault repo from {vstatus} to syncing.")

    mutated = False
    for r in vault_repos:
        if isinstance(r, dict) and r.get("id") == vault_repo_id:
            r["status"] = "syncing"
            r["updated_at"] = now
            r["last_error"] = None
            mutated = True
            break
    if not mutated:
        _log("error", api_key_id=api_key_id, workspace_id=ws_id, vault_repo_id=vault_repo_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Vault repo not found for update.")
    _save("vault_repos.json", vault_repos)

    # "Sync" offline: we cannot call GitHub; treat as a cache maintenance operation:
    # - If mode == full: mark existing cache rows as stale (repo_activity) and keep vault_files as-is (no status field there).
    # - If incremental: do nothing to cached datasets.
    # - Always update last_sync_at and last_sync_commit_sha if we can satisfy integrity rule.
    files_touched = 0
    activity_touched = 0

    if mode == "full":
        if "commits" in include or "issues_discussions" in include:
            for a in repo_activity:
                if not isinstance(a, dict):
                    continue
                if a.get("vault_repo_id") != vault_repo_id:
                    continue
                if a.get("status") in ("deleted",):
                    continue
                # mark stale where allowed
                st = a.get("status")
                if st == "active":
                    a["status"] = "stale"
                    a["updated_at"] = now
                    a["indexed_at"] = a.get("indexed_at") or now
                    activity_touched += 1
        if "files" in include:
            # refresh timestamps to simulate reindex; no external fetch
            for f in vault_files:
                if not isinstance(f, dict):
                    continue
                if f.get("vault_repo_id") != vault_repo_id:
                    continue
                if f.get("deleted") is True:
                    continue
                f["indexed_at"] = now
                f["updated_at"] = now
                files_touched += 1

    # Determine last_sync_commit_sha integrity
    # pick most recent commit (active or stale, but not deleted) by committed_at desc that has sha
    commits = []
    for a in repo_activity:
        if not isinstance(a, dict):
            continue
        if a.get("vault_repo_id") != vault_repo_id:
            continue
        if a.get("activity_type") != "commit":
            continue
        if a.get("status") == "deleted":
            continue
        sha = a.get("sha")
        committed_at = a.get("committed_at")
        if isinstance(sha, str) and sha and isinstance(committed_at, str) and committed_at:
            commits.append(a)
    def _parse_dt(s):
        try:
            x = s
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None
    commits.sort(key=lambda r: (_parse_dt(r.get("committed_at") or "") or datetime.datetime.min), reverse=True)
    last_commit_sha = commits[0]["sha"] if commits else None

    # Complete sync: set to active, update last_sync fields
    for r in vault_repos:
        if isinstance(r, dict) and r.get("id") == vault_repo_id:
            # transition syncing -> active allowed?
            cur = r.get("status")
            if cur != "syncing":
                # someone else modified; refuse to claim success without effect
                _log("error", api_key_id=api_key_id, workspace_id=ws_id, vault_repo_id=vault_repo_id, error_code="CONFLICT")
                return _err("CONFLICT", "Vault repo status changed during sync.")
            if "active" not in allowed_trans.get("syncing", set()):
                _log("error", api_key_id=api_key_id, workspace_id=ws_id, vault_repo_id=vault_repo_id, error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Cannot transition vault repo from syncing to active.")
            r["status"] = "active"
            r["last_sync_at"] = now
            # integrity: only set last_sync_commit_sha if it refers to an existing commit
            r["last_sync_commit_sha"] = last_commit_sha
            r["last_error"] = None
            r["updated_at"] = now
            vr_out = dict(r)
            break
    else:
        _log("error", api_key_id=api_key_id, workspace_id=ws_id, vault_repo_id=vault_repo_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Vault repo not found for finalization.")

    # Persist dataset changes (only if we touched them)
    if activity_touched:
        _save("repo_activity.json", repo_activity)
    if files_touched:
        _save("vault_files.json", vault_files)
    _save("vault_repos.json", vault_repos)

    # Update key last_used_at/updated_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    _log("ok", api_key_id=api_key_id, workspace_id=ws_id, vault_repo_id=vault_repo_id)

    return {
        "sync_receipt": {
            "id": "obgh_sync_" + uuid.uuid4().hex[:24],
            "vault_repo_id": vault_repo_id,
            "mode": mode,
            "ref": ref,
            "include": include,
            "since": since,
            "forced": bool(force) if force is not None else False,
            "started_at": now,  # offline implementation does not track separate start/end precisely
            "finished_at": now,
            "result": "success",
            "counts": {
                "files_touched": files_touched,
                "activity_touched": activity_touched
            }
        },
        "vault_repo": vr_out
    }

def getVaultRepo(vault_repo_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0147000" if __import__("os").path.isdir("./environment_mix/0147000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, api_key_id=None, workspace_id=None, vault_repo_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "obgh_req_" + uuid.uuid4().hex[:24],
                "endpoint": "getVaultRepo",
                "timestamp": now,
                "status": status,
                "latency_ms": int((time.time() - _t0) * 1000),
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "vault_repo_id": vault_repo_id,
                "error_code": error_code
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate
    if not isinstance(vault_repo_id, str) or not vault_repo_id:
        _log("error", error_code="VALIDATION_ERROR", vault_repo_id=vault_repo_id)
        return _err("VALIDATION_ERROR", "vault_repo_id must be a non-empty string.")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    vault_repos = _load("vault_repos.json")

    vr = next((r for r in vault_repos if isinstance(r, dict) and r.get("id") == vault_repo_id), None)
    if not vr:
        _log("error", error_code="NOT_FOUND", vault_repo_id=vault_repo_id)
        return _err("NOT_FOUND", "Vault repo not found.")

    ws_id = vr.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
    if not ws:
        _log("error", error_code="UNAUTHORIZED", vault_repo_id=vault_repo_id)
        return _err("UNAUTHORIZED", "Workspace not accessible.")

    if ws.get("status") == "deleted":
        _log("error", error_code="UNAUTHORIZED", workspace_id=ws_id, vault_repo_id=vault_repo_id)
        return _err("UNAUTHORIZED", "Workspace is deleted.")
    if ws.get("status") == "suspended":
        _log("error", error_code="UNAUTHORIZED", workspace_id=ws_id, vault_repo_id=vault_repo_id)
        return _err("UNAUTHORIZED", "Workspace is suspended.")

    # Ambient auth: must have at least one active key in this workspace, and enforce rate limit
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"]
    if not active_keys:
        _log("error", error_code="UNAUTHORIZED", workspace_id=ws_id, vault_repo_id=vault_repo_id)
        return _err("UNAUTHORIZED", "No active API key available for this workspace.")

    def _within_last_minute(ts_iso, now_dt):
        try:
            s = ts_iso
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return (now_dt - dt.astimezone(datetime.timezone.utc)).total_seconds() < 60
        except Exception:
            return False

    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    chosen_key = None
    for k in sorted(active_keys, key=lambda x: (str(x.get("id") or ""), str(x.get("created_at") or ""))):
        rl = k.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1:
            continue
        recent = 0
        kid = k.get("id")
        for rec in logs:
            if isinstance(rec, dict) and rec.get("api_key_id") == kid and isinstance(rec.get("timestamp"), str):
                if _within_last_minute(rec["timestamp"], now_dt):
                    recent += 1
        if recent < rl:
            chosen_key = k
            break

    if not chosen_key:
        _log("error", error_code="RATE_LIMIT", workspace_id=ws_id, vault_repo_id=vault_repo_id)
        return _err("RATE_LIMIT", "Rate limit exceeded for available API keys.")

    api_key_id = chosen_key.get("id")

    # Update last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    _log("ok", api_key_id=api_key_id, workspace_id=ws_id, vault_repo_id=vault_repo_id)

    return {"vault_repo": dict(vr)}
